def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    rich_pressure = 0.0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('budget', 0) > budget * 0.8:
                    rich_pressure = max(rich_pressure, bid)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_tight = (supply <= 17)
    supply_loose = (supply >= 22)

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1

    if supply_tight:
        urgency += 1
    elif supply_loose:
        urgency -= 1

    if budget < DAILY_SALARY * 2:
        urgency += 1

    if urgency <= 0:
        base = max(8.0, avg_prev * 0.45)
    elif urgency == 1:
        base = max(18.0, avg_prev * 0.65)
    elif urgency == 2:
        base = max(32.0, highest_prev * 0.72)
    elif urgency == 3:
        base = max(48.0, highest_prev + 2.0)
    else:
        base = max(62.0, highest_prev + 6.0)

    if rich_pressure > 0 and urgency >= 3:
        base = max(base, rich_pressure + 3.0)

    if supply_loose and urgency <= 1:
        base *= 0.82
    if supply_tight and urgency >= 2:
        base *= 1.08

    max_safe = budget
    if hp > 4 and no_water == 0:
        max_safe = min(max_safe, budget * 0.42)
    elif hp > 2:
        max_safe = min(max_safe, budget * 0.58)

    if urgency >= 4:
        max_safe = budget
    elif urgency == 3:
        max_safe = min(budget, max(max_safe, budget * 0.72))

    bid = min(base, max_safe)
    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, highest_prev + 8.0 if highest_prev > 0 else DAILY_SALARY * 0.9))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = day_context['day']

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If alone, bid low but nonzero to conserve budget.
    if not alive_opps:
        bid = DAILY_SALARY * 0.35
        if budget < bid:
            bid = budget
        return float(bid)

    # Extract yesterday bids from previous_trace for immediate pressure.
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    pressure = 0.0
    if yesterday_bids:
        pressure = max(yesterday_bids)

    # Supply factor: with 15-25 supply, water per winner is limited.
    # Higher supply allows lower bids; lower supply requires higher bids.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base bid targeting mid-high competitiveness.
    base = DAILY_SALARY * (0.62 - 0.18 * supply_ratio)  # ~0.62 at low supply, ~0.44 at high

    # React to yesterday max pressure: if others were willing to pay big, we must match more.
    # Eric died after low bids, so ignore low-pressure outliers by only using max.
    if pressure >= DAILY_SALARY * 0.85:
        base *= 1.18
    elif pressure >= DAILY_SALARY * 0.65:
        base *= 1.08

    # Urgency based on our hp and consecutive no-water days.
    urgency = 1.0
    if hp <= 2.0:
        urgency = 1.55
    elif hp <= 4.0:
        urgency = 1.25
    if no_water_days >= 2:
        urgency *= 1.20
    if no_water_days >= 3:
        urgency *= 1.10

    bid = base * urgency

    # Budget safety: if budget is low, cap aggressively.
    # Also avoid bidding more than we can afford.
    if budget <= 0:
        return 0.0

    # Keep some budget for later days; still try to survive.
    # If hp is very low, spend more.
    reserve_fraction = 0.25 if hp <= 3.0 else 0.40
    max_affordable = budget * (1.0 - reserve_fraction)
    bid = min(bid, max_affordable)

    # Ensure non-negative and at most budget.
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    # If we are about to be desperate, ensure a minimum bid floor to compete.
    if hp <= 3.0 and bid < DAILY_SALARY * 0.55:
        bid = min(budget, DAILY_SALARY * 0.85)

    return float(bid)

